'use strict';
window.RitmModel=(()=>{
 const DATE='2026-10-27', addDay=(n)=>{const d=new Date(DATE+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
 function defaultTax(){return {income:4800000,contributions:90000,priorAdvances:132000,employees:true}}
 function estimateTax(c){const gross=Math.floor((c.income*6+50)/100),deduction=Math.min(c.contributions,c.employees?Math.floor(gross/2):gross);return {gross,deduction,payable:Math.max(0,gross-deduction-c.priorAdvances),due:'2026-10-28'}}
 function initial(){return {version:2,balance:220400,tax:defaultTax(),expenses:[],done:[],payments:[{id:'supply',name:'Поставка зерна и молока',category:'Закупки',amount:45000,day:2,paid:false},{id:'salary',name:'Зарплата команды',category:'Команда',amount:70000,day:5,paid:false},{id:'tax',name:'Аванс УСН за 9 месяцев',category:'Налоги',amount:66000,day:1,paid:false},{id:'rent',name:'Аренда кофейни',category:'Аренда',amount:108000,day:12,paid:false}]}}
 function history(period){return Array.from({length:period},(_,j)=>{const i=90-period+j;let orders=34+(i*17)%19;if(i%7===5||i%7===6)orders+=12;let avg=445+(i*7)%38;if(i>75)avg-=(i-75)*5;const refunds=i%9===0?avg:0;const revenue=orders*avg;return {date:addDay(i-89),revenue,refunds,expenses:Math.floor(revenue*57/100)+1500,orders}})}
 function adjustedHistory(s,period){return history(period).map(h=>{const v=(s.revenueDays||[]).find(v=>v.date===h.date);return v?{...h,revenue:v.amount,refunds:0,orders:v.orders}:h})}
 function revenueAdjustment(s){return history(90).reduce((n,h)=>{const v=(s.revenueDays||[]).find(v=>v.date===h.date);return n+(v?v.amount-h.revenue+h.refunds:0)},0)}
 function available(s){return s.balance+revenueAdjustment(s)-s.expenses.reduce((n,e)=>n+e.amount,0)-s.payments.filter(p=>p.paid).reduce((n,p)=>n+p.amount,0)}
 function withRevenue(s,v){const next=structuredClone(s);next.revenueDays=(next.revenueDays||[]).filter(d=>d.date!==v.date).concat(v);return next}
 function withCashPlan(s,v){const next=structuredClone(s);next.balance+=v.balance-available(s);next.plan={dailyRevenue:v.dailyRevenue,dailyExpenses:v.dailyExpenses};return next}
 function planValues(s){if(s.plan)return s.plan;return {dailyRevenue:Math.round(Array.from({length:14},(_,i)=>12300+((i+1)*1100)%4500).reduce((a,b)=>a+b,0)/14),dailyExpenses:11300}}
 function dashboard(s,period=30,uplift=0){
  const hist=adjustedHistory(s,period),d={period,history:hist,forecast:[],revenue:0,profit:0,expenses:0,refunds:0,orders:0,average:0,margin:0,score:0,gap:0,gapDate:''};
  for(const h of hist){d.revenue+=h.revenue-h.refunds;d.refunds+=h.refunds;d.expenses+=h.expenses;d.orders+=h.orders}
  for(const e of s.expenses){if(e.date>=hist[0].date&&e.date<=DATE)d.expenses+=e.amount}
  d.profit=d.revenue-d.expenses;d.average=d.orders?Math.floor(d.revenue/d.orders):0;d.margin=d.revenue?d.profit*100/d.revenue:0;
  let balance=available(s);d.minBalance=balance;if(balance<0){d.gap=-balance;d.gapDate=DATE}
  const dailyExpenses=s.plan?s.plan.dailyExpenses:11300;
  for(let i=1;i<=14;i++){const income=Math.floor((s.plan?s.plan.dailyRevenue:12300+(i*1100)%4500)*(100+uplift)/100);const outflow=dailyExpenses+s.payments.filter(p=>!p.paid&&p.day===i).reduce((n,p)=>n+p.amount,0);balance+=income-outflow;d.forecast.push({date:addDay(i),balance,income,outflow});d.minBalance=Math.min(d.minBalance,balance);if(balance<0&&!d.gapDate)d.gapDate=addDay(i);d.gap=Math.max(d.gap,-balance)}
  const reserve=d.minBalance*.7+d.forecast[13].balance*.3,liquidity=35+35*reserve/(Math.abs(reserve)+Math.max(1,dailyExpenses)*3),profitability=Math.max(0,Math.min(30,d.margin));
  d.liquidityScore=Math.round(liquidity*10)/10;d.profitabilityScore=Math.round(profitability*10)/10;d.score=Math.round((liquidity+profitability)*10)/10;return d
 }
 function answer(q,d,s){q=q.toLowerCase();if(/налог|срок/.test(q)){const c=estimateTax(s.tax||defaultTax());return `В налоговом плане выбран ИП на УСН Доходы 6% без НДС. По данным за 9 месяцев начислено ${c.gross} ₽, вычет взносов — ${c.deduction} ₽, предыдущие авансы — ${(s.tax||defaultTax()).priorAdvances} ₽. К уплате ${c.payable} ₽ до 28 октября 2026. При работниках вычет ограничен 50% налога. Уточните базу и вычеты в налоговом плане. Региональные льготы не учтены.`};if(/прибыл|расход|чек/.test(q))return `За выбранные ${d.period} дней выручка за вычетом возвратов — ${d.revenue} ₽, учтённые операционные расходы — ${d.expenses} ₽, операционная прибыль — ${d.profit} ₽, маржа — ${d.margin.toFixed(1)}%. Средний чек за период — ${d.average} ₽. Проверьте закупочные цены и списания, прежде чем менять цены в меню. Прибыль здесь не равна остатку на счёте и не включает расчёт налога.`;if(/разрыв|прогноз|план|делать/.test(q))return d.gap?`В выбранном сценарии первый отрицательный остаток — ${d.gapDate}, максимальная нехватка за 14 дней — ${d.gap} ₽. В прогноз входят текущий остаток, ожидаемые поступления, ежедневные расходы и обязательства. План: 1) согласовать график закупок; 2) проверить возможность переноса части аренды без штрафов; 3) сравнить сценарий роста выручки на 15%. Это гипотезы для проверки, а не обещание результата. Откройте переключатель сценария на графике.`:'В выбранном сценарии отрицательного остатка на 14 дней нет. Сохраняйте резерв под обязательства и пересматривайте прогноз после новых расходов. Это сценарная оценка, а не гарантия.';return `Я вижу данные кофейни: баланс ${s.balance} ₽ до отмеченных оплат и добавленных расходов, индекс устойчивости ${d.score} из 100. Могу разобрать расходы, объяснить прогноз или составить план действий. Сейчас доступен помощник по данным; для свободного диалога подключите модель в настройках ИИ.`}
 return {DATE,addDay,initial,history,adjustedHistory,dashboard,answer,defaultTax,estimateTax,available,withRevenue,withCashPlan,planValues};
})();
